import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CAUU6m5Y.js";const m=JSON.parse('{"title":"Project Pitch: High-Concurrency Flash Sale Inventory Engine","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),i={name:"00b-project-pitch.md"};function r(s,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-high-concurrency-flash-sale-inventory-engine" tabindex="-1">Project Pitch: High-Concurrency Flash Sale Inventory Engine <a class="header-anchor" href="#project-pitch-high-concurrency-flash-sale-inventory-engine" aria-label="Permalink to &quot;Project Pitch: High-Concurrency Flash Sale Inventory Engine&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built <strong>18-Flash-Sale-Inventory</strong>, a high-concurrency reservation engine in FastAPI, Redis, and SQLAlchemy that handles massive flash-sale traffic surges without overselling a single unit. It combines a virtual waiting room to regulate queue admission, atomic stock reservations using conditional decrement logic and monotonic fencing tokens to execute inventory holds in under one millisecond, and automated timeout workers that immediately restore abandoned holds to the available pool. The system continuously enforces the mathematical invariant that available plus reserved plus sold inventory strictly equals total stock, backed by 96 automated concurrency and chaos tests.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;During flash-sale events—such as limited sneaker drops or concert ticket releases—tens of thousands of concurrent buyers hit checkout in the exact same millisecond. Traditional relational databases immediately crash due to row lock contention, deadlocks, and connection exhaustion, leading to disastrous overselling and negative stock counts.</p><p>To solve this, I designed and built <strong>18-Flash-Sale-Inventory</strong>, an enterprise-grade, zero-oversell inventory reservation platform.</p><p>The architecture addresses the three fundamental failure modes of high-throughput commerce:</p><p><strong>First, Traffic Smoothing via a Virtual Waiting Room (<code>src/flow/waiting_room.py</code>)</strong>: Instead of letting 50,000 requests slam the checkout database simultaneously, incoming shoppers enter a virtual waiting room. The system issues cryptographically signed admission tickets and regulates downstream entry in metered batches based on payment gateway capacity.</p><p><strong>Second, Sub-Millisecond Atomic Stock Reservation (<code>src/stock/reservation.py</code>)</strong>: I decoupled inventory availability checks from heavy database transactions. The reservation service executes an atomic conditional decrement (<code>UPDATE ... WHERE available &gt;= :q</code>). We also pair this with in-memory distributed locking with monotonic fencing tokens (<code>src/transactions/distributed_lock.py</code>), ensuring that even under extreme concurrency, stock availability checks and temporary 10-minute hold creations execute atomically without stale reads.</p><p><strong>Third, Two-Phase Checkout and Automated Stock Rollback (<code>src/flow/checkout.py</code>, <code>src/flow/order_payments.py</code>)</strong>: When a buyer reserves an item, a 300-second hold token is issued. If checkout succeeds, payment is captured idempotently and stock is permanently committed to the ledger. If payment fails or the buyer abandons checkout, an asynchronous reconciliation engine automatically expires the hold and replenishes available stock.</p><p><strong>Observability and Invariant Verification (<code>src/observability/oversell.py</code>)</strong>: The system continuously checks the core invariant: <strong>Available + Reserved + Sold == Total Allocated</strong>. A background audit engine detects any mathematical drift or negative inventory in real time.</p><p>The entire engine is covered by 96 automated tests, including multi-threaded race condition tests, chaos cache dropouts, and timezone-aware DST flash-sale activations.&quot;</p></blockquote>',6)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
